/** Renders the report body text.
 *
 * `template_report` (and the LLM writer) emit a small, fixed Markdown subset:
 * `## heading`, `- item`, `  - nested item`, and blank-line-separated
 * paragraphs. The report used to print that straight into a
 * `whitespace-pre-wrap` block, so patients saw literal "##" and "-" markers.
 *
 * This is deliberately not a Markdown library: the input is generated by our
 * own template, the grammar is four cases wide, and a parser we control means
 * no third-party HTML ever reaches a patient-facing medical document.
 */

type Block =
  | { kind: "heading"; text: string }
  | { kind: "list"; items: { text: string; nested: boolean }[] }
  | { kind: "para"; text: string };

function parse(src: string): Block[] {
  const blocks: Block[] = [];
  let list: { text: string; nested: boolean }[] | null = null;
  let para: string[] = [];

  const flushList = () => {
    if (list && list.length) blocks.push({ kind: "list", items: list });
    list = null;
  };
  const flushPara = () => {
    if (para.length) blocks.push({ kind: "para", text: para.join(" ") });
    para = [];
  };

  for (const raw of src.split("\n")) {
    const line = raw.trimEnd();

    if (!line.trim()) {
      flushList();
      flushPara();
      continue;
    }

    if (line.startsWith("## ")) {
      flushList();
      flushPara();
      blocks.push({ kind: "heading", text: line.slice(3).trim() });
      continue;
    }

    // "- item" at column 0, or an indented "  - item" continuation
    const bullet = /^(\s*)[-*]\s+(.*)$/.exec(line);
    if (bullet) {
      flushPara();
      if (!list) list = [];
      list.push({ text: bullet[2].trim(), nested: bullet[1].length >= 2 });
      continue;
    }

    flushList();
    para.push(line.trim());
  }
  flushList();
  flushPara();
  return blocks;
}

/** Which blocks only re-list the plan. The letter is written to stand alone,
 * so it spells out the week's meals, the foods, the recipes and the
 * exercises; printed, those follow as tables and would be on paper twice. A
 * list or paragraph counts when it names three or more plan lines, and a
 * heading goes with the block under it. Anything else always prints. */
function relisted(blocks: Block[], names: string[]): boolean[] {
  const wanted = [...new Set(names.map((n) => n.trim().toLowerCase()))].filter((n) => n.length > 3);
  const out = blocks.map((b) => {
    if (b.kind === "heading") return false;
    const body = (b.kind === "list" ? b.items.map((it) => it.text).join("\n") : b.text).toLowerCase();
    return wanted.filter((name) => body.includes(name)).length >= 3;
  });
  blocks.forEach((b, i) => {
    if (b.kind === "heading") out[i] = out[i + 1] ?? false;
  });
  return out;
}

export function ReportProse({
  text,
  tabled = [],
}: {
  text: string;
  /** names of the plan lines the printed report sets out again as tables */
  tabled?: string[];
}) {
  const blocks = parse(text);
  const offPaper = relisted(blocks, tabled);

  return (
    <div className="space-y-3 text-base leading-7 text-ink print:leading-6">
      {blocks.map((b, i) => {
        const print = offPaper[i] ? "print:hidden" : "";

        if (b.kind === "heading") {
          return (
            <h3
              key={i}
              className={`mt-7 text-base font-semibold text-ink first:mt-0 print:mt-5 ${print}`}
            >
              {b.text}
            </h3>
          );
        }

        if (b.kind === "list") {
          return (
            <ul key={i} className={`space-y-1.5 print:space-y-1 ${print}`}>
              {b.items.map((it, j) => (
                <li
                  key={j}
                  className={`flex gap-2.5 ${it.nested ? "ml-5 text-sm text-ink-soft" : ""}`}
                >
                  <span
                    aria-hidden="true"
                    className={`mt-2.5 h-1 w-1 shrink-0 rounded-full ${
                      it.nested ? "bg-line-strong" : "bg-clinical"
                    }`}
                  />
                  <span>{it.text}</span>
                </li>
              ))}
            </ul>
          );
        }

        return (
          <p key={i} className={`whitespace-pre-line ${print}`}>
            {b.text}
          </p>
        );
      })}
    </div>
  );
}
